CREATE TABLE automation_mail_actions(id TEXT PRIMARY KEY, automation_id TEXT NOT NULL, run_id TEXT, mailbox TEXT NOT NULL, msg_id TEXT NOT NULL, action TEXT NOT NULL, args_json TEXT NOT NULL, state TEXT NOT NULL, created TEXT NOT NULL, claimed_at TEXT, claimed_by TEXT, result_json TEXT, attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE automation_runs(id TEXT PRIMARY KEY, automation_id TEXT NOT NULL, version INTEGER NOT NULL, trigger_ref TEXT NOT NULL DEFAULT '', started TEXT NOT NULL, finished TEXT, status TEXT NOT NULL, cost REAL NOT NULL DEFAULT 0, state_json TEXT, claimed_at TEXT, wake_at TEXT, chain_json TEXT NOT NULL DEFAULT '[]');
CREATE TABLE automation_turn_answers(run_id TEXT NOT NULL, ref TEXT NOT NULL, text TEXT NOT NULL, cost REAL NOT NULL, ok INTEGER NOT NULL, at TEXT NOT NULL, PRIMARY KEY(run_id, ref));
CREATE TABLE automation_versions(automation_id TEXT NOT NULL, n INTEGER NOT NULL, actor TEXT NOT NULL, at TEXT NOT NULL, flow_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', summary TEXT, PRIMARY KEY(automation_id, n));
CREATE TABLE automations(id TEXT PRIMARY KEY, name TEXT NOT NULL, owner TEXT NOT NULL, grp TEXT, trigger_type TEXT NOT NULL, enabled INTEGER NOT NULL, builtin INTEGER NOT NULL DEFAULT 0, flow_json TEXT NOT NULL, version INTEGER NOT NULL, created TEXT NOT NULL, created_by TEXT NOT NULL, updated TEXT NOT NULL, deleted_at TEXT, next_due TEXT, found_since TEXT);
CREATE TABLE backup_verified_blobs(
