CREATE TABLE blob_purges(digest TEXT PRIMARY KEY, kind TEXT NOT NULL DEFAULT '', queued TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, error TEXT NOT NULL DEFAULT '');
CREATE TABLE blobs(
