 blob_id TEXT NOT NULL REFERENCES blobs(id), digest TEXT NOT NULL, source_digest TEXT,
 size INTEGER NOT NULL, name TEXT NOT NULL, mime TEXT NOT NULL, commit_sha TEXT, repo_path TEXT,
 attempt_id TEXT, actor TEXT NOT NULL, created TEXT NOT NULL, width INTEGER, height INTEGER, duration_ms INTEGER, poster_blob_id TEXT REFERENCES blobs(id), thumb_blob_id TEXT REFERENCES blobs(id), media_state TEXT NOT NULL DEFAULT 'none'
