 PRIMARY KEY(bot, runtime, model));
CREATE TABLE bot_status (
  bot TEXT PRIMARY KEY, state TEXT, focus TEXT, task_id TEXT, since TEXT, last_turn_at TEXT,
  last_result TEXT, next_due TEXT, open_tasks INTEGER DEFAULT 0, needs_human INTEGER DEFAULT 0,
  updated_at TEXT);
CREATE TABLE bot_status_history (
  id TEXT PRIMARY KEY, bot TEXT, state TEXT, focus TEXT, task_id TEXT,
  since TEXT, until TEXT, reason TEXT, by TEXT);
CREATE TABLE bot_task_tabs (
  bot TEXT NOT NULL, viewer TEXT NOT NULL DEFAULT '', tabs_json TEXT NOT NULL,
  updated TEXT NOT NULL, updated_by TEXT NOT NULL, widgets_json TEXT, PRIMARY KEY (bot, viewer));
CREATE TABLE bot_tool_requests(
