CREATE TABLE cards (
  id TEXT PRIMARY KEY, template TEXT NOT NULL, settings_json TEXT NOT NULL DEFAULT '{}', title TEXT NOT NULL DEFAULT '',
  made_by TEXT NOT NULL, created TEXT NOT NULL, updated TEXT NOT NULL, updated_by TEXT NOT NULL);
