 PRIMARY KEY(kind,owner));
CREATE TABLE conversations (
  id TEXT PRIMARY KEY, kind TEXT, subject TEXT, task_id TEXT, participants_json TEXT,
  created TEXT, last_message_at TEXT, closed_at TEXT, scope TEXT NOT NULL DEFAULT 'direct', owner_actor TEXT, room_key TEXT);
CREATE TABLE credential_grants(
 id TEXT PRIMARY KEY, credential_id TEXT NOT NULL REFERENCES credentials(id),
 subject TEXT NOT NULL, granted_by TEXT NOT NULL, parent_id TEXT REFERENCES credential_grants(id),
 created TEXT NOT NULL, revoked TEXT, revoked_by TEXT);
CREATE TABLE credential_imports(
 id TEXT PRIMARY KEY, requester TEXT NOT NULL, bot TEXT NOT NULL, env TEXT NOT NULL, name TEXT NOT NULL DEFAULT '',
 kind TEXT NOT NULL DEFAULT 'api_key', state TEXT NOT NULL DEFAULT 'requested', message TEXT NOT NULL DEFAULT '',
 credential_id TEXT, created TEXT NOT NULL, updated TEXT NOT NULL);
CREATE TABLE credential_keys(
 id TEXT PRIMARY KEY, kms_key TEXT NOT NULL, wrapped_key BLOB NOT NULL);
CREATE TABLE credential_requests(
 id TEXT PRIMARY KEY, requester TEXT NOT NULL, conversation_id TEXT NOT NULL, bot TEXT NOT NULL, asker TEXT NOT NULL,
 env TEXT NOT NULL, label TEXT NOT NULL DEFAULT '', format TEXT NOT NULL DEFAULT '', help_url TEXT NOT NULL DEFAULT '',
 kind TEXT NOT NULL DEFAULT 'api_key', status TEXT NOT NULL DEFAULT 'pending', created TEXT NOT NULL,
 updated TEXT NOT NULL, credential_id TEXT, message_id TEXT);
CREATE TABLE credential_uses(
 credential_id TEXT NOT NULL, actor TEXT NOT NULL, bot TEXT NOT NULL DEFAULT '', at TEXT NOT NULL,
 logged TEXT NOT NULL DEFAULT '',
 PRIMARY KEY(credential_id, actor, bot));
CREATE TABLE credentials(
 id TEXT PRIMARY KEY, name TEXT NOT NULL, username TEXT NOT NULL DEFAULT '',
 kind TEXT NOT NULL, env TEXT NOT NULL DEFAULT '', preview TEXT NOT NULL DEFAULT '',
 ciphertext BLOB, nonce BLOB, source TEXT NOT NULL DEFAULT '',
 revision INTEGER NOT NULL DEFAULT 1, created TEXT NOT NULL, updated TEXT NOT NULL,
 updated_by TEXT NOT NULL, created_by TEXT, member_stored INTEGER NOT NULL DEFAULT 0);
CREATE TABLE deferrals(id TEXT PRIMARY KEY, bot TEXT NOT NULL, kind TEXT NOT NULL, item TEXT NOT NULL, conversation_id TEXT NOT NULL DEFAULT '', task_id TEXT, due TEXT, created TEXT NOT NULL, fired_job TEXT, settled TEXT, how TEXT, attempt TEXT);
CREATE TABLE deltas (
  id TEXT PRIMARY KEY, turn_id TEXT, seq INTEGER, kind TEXT, text TEXT, ts TEXT);
CREATE TABLE directory_credentials(
 source TEXT PRIMARY KEY, ciphertext BLOB NOT NULL, nonce BLOB NOT NULL, hint TEXT NOT NULL DEFAULT '',
 created TEXT NOT NULL, created_by TEXT NOT NULL);
CREATE TABLE doc_source_jobs(
 source_id TEXT PRIMARY KEY REFERENCES doc_sources(source_id), generation INTEGER NOT NULL,
 lease TEXT NOT NULL DEFAULT '', lease_until REAL NOT NULL DEFAULT 0, next_try REAL NOT NULL DEFAULT 0,
 snapshot_id TEXT, commit_sha TEXT NOT NULL DEFAULT '', inventory_json TEXT, skipped INTEGER NOT NULL DEFAULT 0,
 checked_at TEXT, resolved_at REAL NOT NULL DEFAULT 0);
CREATE TABLE doc_sources(
 source_id TEXT PRIMARY KEY REFERENCES linked_docs(id), url TEXT NOT NULL,
 generation INTEGER NOT NULL DEFAULT 1, reference_override TEXT NOT NULL DEFAULT '',
 repo TEXT NOT NULL DEFAULT '', kind TEXT NOT NULL DEFAULT '', reference TEXT NOT NULL DEFAULT '',
 path TEXT NOT NULL DEFAULT '', active_snapshot TEXT, status TEXT NOT NULL DEFAULT 'link_only',
 last_checked TEXT, next_check REAL NOT NULL DEFAULT 0, skipped INTEGER NOT NULL DEFAULT 0,
 error_code TEXT NOT NULL DEFAULT '');
CREATE TABLE doc_versions(
 doc_id TEXT NOT NULL REFERENCES docs(id), version INTEGER NOT NULL, title TEXT NOT NULL, path TEXT NOT NULL,
 body TEXT NOT NULL, actor TEXT NOT NULL, created TEXT NOT NULL, note TEXT NOT NULL DEFAULT '',
 PRIMARY KEY(doc_id, version));
CREATE TABLE docs(
 id TEXT PRIMARY KEY, path TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL DEFAULT '',
 locked INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1,
 created_by TEXT NOT NULL, created TEXT NOT NULL, updated_by TEXT NOT NULL, updated TEXT NOT NULL,
 archived INTEGER NOT NULL DEFAULT 0);
