 PRIMARY KEY(message_id,blob_id));
CREATE TABLE message_links(message_id TEXT NOT NULL, kind TEXT NOT NULL, target TEXT NOT NULL, PRIMARY KEY(kind, target, message_id)) WITHOUT ROWID;
CREATE TABLE message_links_dirty(message_id TEXT PRIMARY KEY) WITHOUT ROWID;
CREATE TABLE message_links_seen(message_id TEXT PRIMARY KEY) WITHOUT ROWID;
CREATE TABLE messages (
  id TEXT PRIMARY KEY, conversation_id TEXT REFERENCES conversations(id),
  from_actor TEXT, to_actor TEXT, kind TEXT, body TEXT, refs_json TEXT, in_reply_to TEXT,
  created TEXT, delivered_at TEXT, read_at TEXT, expires_at TEXT, wait_s INTEGER, answered_by TEXT, edited_at TEXT, deleted_at TEXT, superseded_at TEXT, public INTEGER NOT NULL DEFAULT 0, hidden_at TEXT);
CREATE TABLE milestones(
  kind TEXT NOT NULL, target TEXT NOT NULL, at TEXT NOT NULL, source TEXT, PRIMARY KEY(kind, target));
CREATE TABLE model_login_cleared(
