CREATE TABLE notes(id TEXT PRIMARY KEY, from_actor TEXT NOT NULL, to_actor TEXT NOT NULL, body TEXT NOT NULL, created TEXT NOT NULL, carried_by TEXT, cancelled_at TEXT, cancelled_by TEXT, message_id TEXT, settled_at TEXT);
CREATE TABLE oauth_clients(
