CREATE TABLE org_rule_holds(id TEXT PRIMARY KEY, operation TEXT NOT NULL, payload_json TEXT NOT NULL, author TEXT NOT NULL, destinations_json TEXT NOT NULL DEFAULT '[]', rule_ids_json TEXT NOT NULL DEFAULT '[]', verdict_json TEXT NOT NULL DEFAULT '{}', why TEXT NOT NULL DEFAULT '', nonce TEXT NOT NULL, state TEXT NOT NULL CHECK (state IN ('held','sent','kept')), reviewer TEXT, task_id TEXT, created TEXT NOT NULL, decided_at TEXT, decided_by TEXT);
