CREATE TRIGGER market_entities_ai AFTER INSERT ON market_entities BEGIN
  INSERT INTO market_fts(kind, ref, name, aliases, summary, quote, our_read)
  VALUES ('entity', new.id, new.name, new.aliases, new.summary, '', '');
END;
CREATE TRIGGER market_entities_ad AFTER DELETE ON market_entities BEGIN
  DELETE FROM market_fts WHERE kind='entity' AND ref=old.id;
END;
CREATE TRIGGER market_entities_au AFTER UPDATE ON market_entities BEGIN
  DELETE FROM market_fts WHERE kind='entity' AND ref=old.id;
  INSERT INTO market_fts(kind, ref, name, aliases, summary, quote, our_read)
  VALUES ('entity', new.id, new.name, new.aliases, new.summary, '', '');
END;
CREATE TRIGGER market_evidence_ai AFTER INSERT ON market_evidence BEGIN
  INSERT INTO market_fts(kind, ref, name, aliases, summary, quote, our_read)
  VALUES ('evidence', new.id, '', '', '', new.quote, new.our_read);
END;
CREATE TRIGGER market_evidence_ad AFTER DELETE ON market_evidence BEGIN
  DELETE FROM market_fts WHERE kind='evidence' AND ref=old.id;
END;
CREATE TRIGGER market_evidence_au AFTER UPDATE ON market_evidence BEGIN
  DELETE FROM market_fts WHERE kind='evidence' AND ref=old.id;
  INSERT INTO market_fts(kind, ref, name, aliases, summary, quote, our_read)
  VALUES ('evidence', new.id, '', '', '', new.quote, new.our_read);
END;
