CREATE TRIGGER market_keys_insert AFTER INSERT ON market_entities BEGIN
                
                INSERT OR IGNORE INTO market_entity_keys SELECT key, new.id FROM (SELECT lower(trim(new.name)) AS key
                UNION SELECT lower(trim(json_extract(CASE WHEN json_valid(new.external_ids) THEN new.external_ids ELSE '{}' END, '$.domain')))
                UNION SELECT lower(trim(value)) FROM json_each(CASE WHEN json_valid(new.aliases) THEN new.aliases ELSE '[]' END))
                    WHERE key IS NOT NULL AND key<>'';
            END;
CREATE TRIGGER market_keys_update AFTER UPDATE OF name, aliases, external_ids ON market_entities BEGIN
                DELETE FROM market_entity_keys WHERE entity_id=old.id;
                INSERT OR IGNORE INTO market_entity_keys SELECT key, new.id FROM (SELECT lower(trim(new.name)) AS key
                UNION SELECT lower(trim(json_extract(CASE WHEN json_valid(new.external_ids) THEN new.external_ids ELSE '{}' END, '$.domain')))
                UNION SELECT lower(trim(value)) FROM json_each(CASE WHEN json_valid(new.aliases) THEN new.aliases ELSE '[]' END))
                    WHERE key IS NOT NULL AND key<>'';
            END;
CREATE TRIGGER market_keys_delete AFTER DELETE ON market_entities BEGIN
            DELETE FROM market_entity_keys WHERE entity_id=old.id;
        END;
