CREATE TRIGGER idempotency_messages_insert AFTER INSERT ON idempotency WHEN (instr(NEW.response_json, '"from_actor"')>0 OR NOT json_valid(NEW.response_json)) BEGIN INSERT OR IGNORE INTO idempotency_messages SELECT id, actor, operation, key FROM (SELECT NEW.actor AS actor, NEW.operation AS operation, NEW.key AS key, max(CASE WHEN t.key='id' AND t.type='text' THEN t.value END) AS id, max(t.key='from_actor') AS sender FROM json_tree(CASE WHEN json_valid(NEW.response_json) THEN NEW.response_json ELSE 'null' END) t WHERE t.key IN ('id','from_actor') GROUP BY t.parent) WHERE sender AND id IS NOT NULL UNION SELECT '*', NEW.actor, NEW.operation, NEW.key WHERE NOT json_valid(NEW.response_json); END;
CREATE TRIGGER idempotency_messages_update AFTER UPDATE ON idempotency BEGIN DELETE FROM idempotency_messages WHERE actor=OLD.actor AND operation=OLD.operation AND key=OLD.key; INSERT OR IGNORE INTO idempotency_messages SELECT id, actor, operation, key FROM (SELECT NEW.actor AS actor, NEW.operation AS operation, NEW.key AS key, max(CASE WHEN t.key='id' AND t.type='text' THEN t.value END) AS id, max(t.key='from_actor') AS sender FROM json_tree(CASE WHEN json_valid(NEW.response_json) THEN NEW.response_json ELSE 'null' END) t WHERE t.key IN ('id','from_actor') GROUP BY t.parent) WHERE sender AND id IS NOT NULL UNION SELECT '*', NEW.actor, NEW.operation, NEW.key WHERE NOT json_valid(NEW.response_json); END;
CREATE TRIGGER idempotency_messages_delete AFTER DELETE ON idempotency BEGIN DELETE FROM idempotency_messages WHERE actor=OLD.actor AND operation=OLD.operation AND key=OLD.key; END;
