CREATE TRIGGER fin_lines_no_update BEFORE UPDATE ON fin_lines
BEGIN SELECT RAISE(ABORT, 'fin_lines are immutable: post a reversing entry'); END;
CREATE TRIGGER fin_lines_no_delete BEFORE DELETE ON fin_lines
BEGIN SELECT RAISE(ABORT, 'fin_lines are immutable: post a reversing entry'); END;
CREATE TRIGGER fin_entries_no_delete BEFORE DELETE ON fin_entries
BEGIN SELECT RAISE(ABORT, 'fin_entries are immutable: post a reversing entry'); END;
CREATE TRIGGER fin_entries_only_reverse BEFORE UPDATE ON fin_entries
WHEN NOT (OLD.status = 'posted' AND NEW.status = 'reversed' AND NEW.id = OLD.id AND NEW.book_id = OLD.book_id
          AND NEW.entry_date = OLD.entry_date AND NEW.memo = OLD.memo AND NEW.source = OLD.source
          AND NEW.source_id = OLD.source_id AND NEW.reverses_id IS OLD.reverses_id AND NEW.period_id IS OLD.period_id
          AND NEW.action_id IS OLD.action_id AND NEW.created_at = OLD.created_at AND NEW.created_by = OLD.created_by)
BEGIN SELECT RAISE(ABORT, 'fin_entries are immutable: only posted -> reversed may change'); END;
CREATE TRIGGER fin_entries_open_period BEFORE INSERT ON fin_entries
WHEN EXISTS (SELECT 1 FROM fin_periods p WHERE p.book_id = NEW.book_id AND p.status = 'closed'
             AND NEW.entry_date BETWEEN p.start_date AND p.end_date)
BEGIN SELECT RAISE(ABORT, 'period closed'); END;
CREATE TRIGGER fin_lines_open_period BEFORE INSERT ON fin_lines
WHEN EXISTS (SELECT 1 FROM fin_periods p WHERE p.book_id = NEW.book_id AND p.status = 'closed'
             AND NEW.entry_date BETWEEN p.start_date AND p.end_date)
BEGIN SELECT RAISE(ABORT, 'period closed'); END;
CREATE TRIGGER fin_view_roster_insert AFTER INSERT ON registry_metadata WHEN NEW.key = 'people' BEGIN UPDATE fin_view_versions SET version=version+1, reason='roster', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=1; END;
CREATE TRIGGER fin_view_roster_update AFTER UPDATE OF value_json ON registry_metadata WHEN NEW.key = 'people' AND OLD.value_json IS NOT NEW.value_json BEGIN UPDATE fin_view_versions SET version=version+1, reason='roster', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=1; END;
