CREATE TRIGGER fin_view_bot_update AFTER UPDATE OF reports_to, config_json ON bot_config WHEN OLD.reports_to IS NOT NEW.reports_to OR CASE WHEN json_valid(OLD.config_json) AND json_valid(NEW.config_json) THEN json_extract(OLD.config_json, '$.team') IS NOT json_extract(NEW.config_json, '$.team') OR json_extract(OLD.config_json, '$.reports_to') IS NOT json_extract(NEW.config_json, '$.reports_to') ELSE OLD.config_json IS NOT NEW.config_json END BEGIN UPDATE fin_view_versions SET version=version+1, reason='reports to', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=1; END;
CREATE TRIGGER fin_view_bot_archive AFTER UPDATE OF state ON bots WHEN (OLD.state = 'archived') IS NOT (NEW.state = 'archived') BEGIN UPDATE fin_view_versions SET version=version+1, reason='bot archived', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=1; END;
