CREATE TRIGGER wake_preset_hold AFTER INSERT ON jobs WHEN NEW.state='queued' BEGIN
 UPDATE jobs SET wake_preset=CASE WHEN (SELECT json_extract(config_json,'$.wake_preset') FROM bot_config
   WHERE bot=NEW.bot)='token_saver' THEN 'token_saver' ELSE 'performance' END WHERE id=NEW.id;
 UPDATE jobs SET held=1,wake_class=(SELECT CASE WHEN json_extract(m.refs_json,'$.wake_batch') IN ('completion','review','ci','rule') THEN json_extract(m.refs_json,'$.wake_batch')
   ELSE 'sweep' END FROM messages m WHERE m.id=NEW.message_id)
   WHERE id=NEW.id AND (SELECT wake_preset FROM jobs WHERE id=NEW.id) IN ('token_saver','performance') AND EXISTS(SELECT 1 FROM messages m WHERE m.id=NEW.message_id
   AND m.from_actor='keeper' AND coalesce(json_extract(m.refs_json,'$.wake_immediate'),0)<>1
   AND (json_extract(m.refs_json,'$.wake_batch') IN ('completion','review','ci','rule') OR (json_extract(m.refs_json,'$.wake') IN ('stalled','status_check','occurrence') OR json_extract(m.refs_json,'$.sweep') IS NOT NULL)));
 UPDATE jobs SET state='cancelled',held=0,wake_class='duplicate' WHERE id=NEW.id AND (SELECT wake_preset FROM jobs WHERE id=NEW.id) IN ('token_saver','performance')
   AND (EXISTS(SELECT 1 FROM messages m JOIN messages om ON m.from_actor='keeper' AND om.conversation_id=m.conversation_id AND om.rowid<m.rowid
   JOIN jobs o ON o.message_id=om.id AND o.bot=NEW.bot AND o.id<>NEW.id
   AND (o.state<>'cancelled' OR o.wake_carrier IS NOT NULL)
   LEFT JOIN jobs cj ON cj.id=o.wake_carrier LEFT JOIN attempts a ON a.id=coalesce(cj.attempt_id,o.attempt_id)
   WHERE m.id=NEW.message_id AND om.from_actor IS m.from_actor AND om.kind IS m.kind AND om.body=m.body AND om.refs_json IS m.refs_json AND om.in_reply_to IS m.in_reply_to AND (coalesce(cj.state,o.state) IN ('queued','leased','running','input')
   OR a.finished>=strftime('%Y-%m-%dT%H:%M:%fZ',m.created,'-120 seconds'))) OR EXISTS(SELECT 1 FROM messages m JOIN messages om ON om.rowid=(SELECT max(x.rowid) FROM messages x WHERE x.conversation_id=m.conversation_id AND x.rowid<m.rowid)
   JOIN jobs o ON o.message_id=om.id AND o.bot=NEW.bot AND o.id<>NEW.id
   AND (o.state<>'cancelled' OR o.wake_carrier IS NOT NULL)
   LEFT JOIN jobs cj ON cj.id=o.wake_carrier LEFT JOIN attempts a ON a.id=coalesce(cj.attempt_id,o.attempt_id)
   WHERE m.id=NEW.message_id AND om.from_actor IS m.from_actor AND om.kind IS m.kind AND om.body=m.body AND om.refs_json IS m.refs_json AND om.in_reply_to IS m.in_reply_to AND (coalesce(cj.state,o.state) IN ('queued','leased','running','input')
   OR a.finished>=strftime('%Y-%m-%dT%H:%M:%fZ',m.created,'-120 seconds'))));
END;
