CREATE TRIGGER changes_tasks_insert AFTER INSERT ON tasks BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,at) SELECT 'tasks','insert',NEW.id,NULL,NULL,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now');INSERT INTO changes(topic,kind,subject_id,at) SELECT 'needs','task',who,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT NEW.owner AS who UNION SELECT NEW.requester AS who UNION SELECT NEW.waiting_on AS who UNION SELECT NEW.guest AS who) WHERE who LIKE 'human:%'; END;
CREATE TRIGGER changes_tasks_update AFTER UPDATE ON tasks BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,at) SELECT 'tasks','update',NEW.id,CASE WHEN OLD.owner IS NOT NEW.owner OR OLD.requester IS NOT NEW.requester OR OLD.private IS NOT NEW.private OR OLD.guest IS NOT NEW.guest THEN json_array(OLD.owner,OLD.requester,OLD.private,OLD.guest) END,NULL,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now');INSERT INTO changes(topic,kind,subject_id,at) SELECT 'needs','task',who,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT OLD.owner AS who UNION SELECT OLD.requester AS who UNION SELECT OLD.waiting_on AS who UNION SELECT OLD.guest AS who UNION SELECT NEW.owner AS who UNION SELECT NEW.requester AS who UNION SELECT NEW.waiting_on AS who UNION SELECT NEW.guest AS who) WHERE who LIKE 'human:%'; END;
CREATE TRIGGER changes_tasks_delete AFTER DELETE ON tasks BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,at) SELECT 'tasks','delete',OLD.id,json_array(OLD.owner,OLD.requester,OLD.private,OLD.guest),NULL,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now');INSERT INTO changes(topic,kind,subject_id,at) SELECT 'needs','task',who,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT OLD.owner AS who UNION SELECT OLD.requester AS who UNION SELECT OLD.waiting_on AS who UNION SELECT OLD.guest AS who) WHERE who LIKE 'human:%'; END;
