CREATE TRIGGER changes_task_links_update AFTER UPDATE ON task_links WHEN OLD.activity_at IS NOT NEW.activity_at OR OLD.added_by IS NOT NEW.added_by OR OLD.branch IS NOT NEW.branch OR OLD.checks IS NOT NEW.checks OR OLD.computer_id IS NOT NEW.computer_id OR OLD.created IS NOT NEW.created OR OLD.detail_json IS NOT NEW.detail_json OR OLD.id IS NOT NEW.id OR OLD.kind IS NOT NEW.kind OR OLD.mergeable IS NOT NEW.mergeable OR OLD.number IS NOT NEW.number OR OLD.path IS NOT NEW.path OR OLD.pending_comments IS NOT NEW.pending_comments OR OLD.pr_merged_at IS NOT NEW.pr_merged_at OR OLD.pr_sha IS NOT NEW.pr_sha OR OLD.repo IS NOT NEW.repo OR OLD.review_state IS NOT NEW.review_state OR OLD.state IS NOT NEW.state OR OLD.task_id IS NOT NEW.task_id OR OLD.title IS NOT NEW.title OR OLD.updated IS NOT NEW.updated OR OLD.url IS NOT NEW.url BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,at) SELECT 'tasks','link',NEW.task_id,NULL,NULL,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;
