CREATE TRIGGER changes_bot_files_update AFTER UPDATE ON bot_files WHEN (NEW.task_id IS NOT NULL OR OLD.task_id IS NOT NULL) AND (OLD.task_id IS NOT NEW.task_id OR OLD.archived IS NOT NEW.archived OR OLD.current_version IS NOT NEW.current_version OR OLD.mime IS NOT NEW.mime OR OLD.locator IS NOT NEW.locator) BEGIN INSERT INTO changes(topic,kind,subject_id,at) SELECT 'tasks','files',id,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT id FROM (SELECT NEW.task_id AS id UNION SELECT OLD.task_id) WHERE id IS NOT NULL) WHERE NOT (SELECT count(*) FROM (SELECT 1 FROM (SELECT id FROM (SELECT NEW.task_id AS id UNION SELECT OLD.task_id) WHERE id IS NOT NULL) LIMIT 101))>100;INSERT INTO changes(topic,kind,at) SELECT 'tasks','bulk',strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE (SELECT count(*) FROM (SELECT 1 FROM (SELECT id FROM (SELECT NEW.task_id AS id UNION SELECT OLD.task_id) WHERE id IS NOT NULL) LIMIT 101))>100; END;
CREATE TRIGGER changes_blob_media_insert AFTER INSERT ON blob_media WHEN NEW.width IS NOT NULL OR NEW.height IS NOT NULL OR NEW.thumb_blob_id IS NOT NULL OR NEW.poster_blob_id IS NOT NULL BEGIN INSERT INTO changes(topic,kind,subject_id,at) SELECT 'tasks','files',id,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT id FROM (SELECT task_id AS id FROM task_assets WHERE blob_id=NEW.blob_id UNION SELECT f.task_id FROM bot_file_versions v JOIN bot_files f ON f.id=v.file_id WHERE v.blob_id=NEW.blob_id) WHERE id IS NOT NULL) WHERE NOT (SELECT count(*) FROM (SELECT 1 FROM (SELECT id FROM (SELECT task_id AS id FROM task_assets WHERE blob_id=NEW.blob_id UNION SELECT f.task_id FROM bot_file_versions v JOIN bot_files f ON f.id=v.file_id WHERE v.blob_id=NEW.blob_id) WHERE id IS NOT NULL) LIMIT 101))>100;INSERT INTO changes(topic,kind,at) SELECT 'tasks','bulk',strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE (SELECT count(*) FROM (SELECT 1 FROM (SELECT id FROM (SELECT task_id AS id FROM task_assets WHERE blob_id=NEW.blob_id UNION SELECT f.task_id FROM bot_file_versions v JOIN bot_files f ON f.id=v.file_id WHERE v.blob_id=NEW.blob_id) WHERE id IS NOT NULL) LIMIT 101))>100; END;
CREATE TRIGGER changes_blob_media_update AFTER UPDATE ON blob_media WHEN OLD.width IS NOT NEW.width OR OLD.height IS NOT NEW.height OR OLD.thumb_blob_id IS NOT NEW.thumb_blob_id OR OLD.poster_blob_id IS NOT NEW.poster_blob_id BEGIN INSERT INTO changes(topic,kind,subject_id,at) SELECT 'tasks','files',id,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT id FROM (SELECT task_id AS id FROM task_assets WHERE blob_id=NEW.blob_id UNION SELECT f.task_id FROM bot_file_versions v JOIN bot_files f ON f.id=v.file_id WHERE v.blob_id=NEW.blob_id) WHERE id IS NOT NULL) WHERE NOT (SELECT count(*) FROM (SELECT 1 FROM (SELECT id FROM (SELECT task_id AS id FROM task_assets WHERE blob_id=NEW.blob_id UNION SELECT f.task_id FROM bot_file_versions v JOIN bot_files f ON f.id=v.file_id WHERE v.blob_id=NEW.blob_id) WHERE id IS NOT NULL) LIMIT 101))>100;INSERT INTO changes(topic,kind,at) SELECT 'tasks','bulk',strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE (SELECT count(*) FROM (SELECT 1 FROM (SELECT id FROM (SELECT task_id AS id FROM task_assets WHERE blob_id=NEW.blob_id UNION SELECT f.task_id FROM bot_file_versions v JOIN bot_files f ON f.id=v.file_id WHERE v.blob_id=NEW.blob_id) WHERE id IS NOT NULL) LIMIT 101))>100; END;
