CREATE TRIGGER changes_task_asks_insert AFTER INSERT ON messages WHEN NEW.kind IN ('ask','answer') BEGIN INSERT INTO changes(topic,kind,subject_id,at) SELECT 'tasks','ask',id,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT id FROM (SELECT (SELECT coalesce(CASE WHEN json_type(m.refs_json,'$.task')='array' THEN json_extract(m.refs_json,'$.task[0]') ELSE json_extract(m.refs_json,'$.task') END, CASE WHEN json_type(m.refs_json,'$.task_id')='array' THEN json_extract(m.refs_json,'$.task_id[0]') ELSE json_extract(m.refs_json,'$.task_id') END, cv.task_id) FROM messages m LEFT JOIN conversations cv ON cv.id=m.conversation_id WHERE m.id=NEW.id) AS id) WHERE id IS NOT NULL) WHERE NOT (SELECT count(*) FROM (SELECT 1 FROM (SELECT id FROM (SELECT (SELECT coalesce(CASE WHEN json_type(m.refs_json,'$.task')='array' THEN json_extract(m.refs_json,'$.task[0]') ELSE json_extract(m.refs_json,'$.task') END, CASE WHEN json_type(m.refs_json,'$.task_id')='array' THEN json_extract(m.refs_json,'$.task_id[0]') ELSE json_extract(m.refs_json,'$.task_id') END, cv.task_id) FROM messages m LEFT JOIN conversations cv ON cv.id=m.conversation_id WHERE m.id=NEW.id) AS id) WHERE id IS NOT NULL) LIMIT 101))>100;INSERT INTO changes(topic,kind,at) SELECT 'tasks','bulk',strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE (SELECT count(*) FROM (SELECT 1 FROM (SELECT id FROM (SELECT (SELECT coalesce(CASE WHEN json_type(m.refs_json,'$.task')='array' THEN json_extract(m.refs_json,'$.task[0]') ELSE json_extract(m.refs_json,'$.task') END, CASE WHEN json_type(m.refs_json,'$.task_id')='array' THEN json_extract(m.refs_json,'$.task_id[0]') ELSE json_extract(m.refs_json,'$.task_id') END, cv.task_id) FROM messages m LEFT JOIN conversations cv ON cv.id=m.conversation_id WHERE m.id=NEW.id) AS id) WHERE id IS NOT NULL) LIMIT 101))>100; END;
CREATE TRIGGER changes_task_asks_update AFTER UPDATE ON messages WHEN NEW.kind='ask' AND (OLD.answered_by IS NOT NEW.answered_by OR OLD.deleted_at IS NOT NEW.deleted_at OR OLD.kind IS NOT NEW.kind OR OLD.superseded_at IS NOT NEW.superseded_at) BEGIN INSERT INTO changes(topic,kind,subject_id,at) SELECT 'tasks','ask',id,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT id FROM (SELECT (SELECT coalesce(CASE WHEN json_type(m.refs_json,'$.task')='array' THEN json_extract(m.refs_json,'$.task[0]') ELSE json_extract(m.refs_json,'$.task') END, CASE WHEN json_type(m.refs_json,'$.task_id')='array' THEN json_extract(m.refs_json,'$.task_id[0]') ELSE json_extract(m.refs_json,'$.task_id') END, cv.task_id) FROM messages m LEFT JOIN conversations cv ON cv.id=m.conversation_id WHERE m.id=NEW.id) AS id) WHERE id IS NOT NULL) WHERE NOT (SELECT count(*) FROM (SELECT 1 FROM (SELECT id FROM (SELECT (SELECT coalesce(CASE WHEN json_type(m.refs_json,'$.task')='array' THEN json_extract(m.refs_json,'$.task[0]') ELSE json_extract(m.refs_json,'$.task') END, CASE WHEN json_type(m.refs_json,'$.task_id')='array' THEN json_extract(m.refs_json,'$.task_id[0]') ELSE json_extract(m.refs_json,'$.task_id') END, cv.task_id) FROM messages m LEFT JOIN conversations cv ON cv.id=m.conversation_id WHERE m.id=NEW.id) AS id) WHERE id IS NOT NULL) LIMIT 101))>100;INSERT INTO changes(topic,kind,at) SELECT 'tasks','bulk',strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE (SELECT count(*) FROM (SELECT 1 FROM (SELECT id FROM (SELECT (SELECT coalesce(CASE WHEN json_type(m.refs_json,'$.task')='array' THEN json_extract(m.refs_json,'$.task[0]') ELSE json_extract(m.refs_json,'$.task') END, CASE WHEN json_type(m.refs_json,'$.task_id')='array' THEN json_extract(m.refs_json,'$.task_id[0]') ELSE json_extract(m.refs_json,'$.task_id') END, cv.task_id) FROM messages m LEFT JOIN conversations cv ON cv.id=m.conversation_id WHERE m.id=NEW.id) AS id) WHERE id IS NOT NULL) LIMIT 101))>100; END;
