CREATE TRIGGER changes_messages_insert AFTER INSERT ON messages BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,at) SELECT 'messages','insert',NEW.id,NULL,NEW.conversation_id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now');INSERT INTO changes(topic,kind,subject_id,at) SELECT 'needs','ask',who,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT NEW.to_actor AS who UNION SELECT NEW.from_actor AS who) WHERE who LIKE 'human:%' AND NEW.kind IN ('ask','answer'); END;
