CREATE INDEX read_deps_key ON read_deps(key);
CREATE TRIGGER read_deps_message_insert AFTER INSERT ON messages BEGIN INSERT OR IGNORE INTO read_dirty VALUES('m:'||NEW.id); INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='m:'||NEW.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='m:'||NEW.id); INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='t:'||NEW.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='t:'||NEW.id); INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='c:'||NEW.conversation_id AND instr(coalesce(NEW.refs_json,''),'live_meeting')>0; DELETE FROM read_index WHERE instr(coalesce(NEW.refs_json,''),'live_meeting')>0 AND key IN (SELECT key FROM read_deps WHERE dep='c:'||NEW.conversation_id); END;
CREATE TRIGGER read_deps_message_update AFTER UPDATE OF id,conversation_id,refs_json,in_reply_to,from_actor,to_actor ON messages WHEN OLD.id IS NOT NEW.id OR OLD.conversation_id IS NOT NEW.conversation_id OR OLD.refs_json IS NOT NEW.refs_json OR OLD.in_reply_to IS NOT NEW.in_reply_to OR OLD.from_actor IS NOT NEW.from_actor OR OLD.to_actor IS NOT NEW.to_actor BEGIN INSERT OR IGNORE INTO read_dirty VALUES('m:'||NEW.id); INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='m:'||OLD.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='m:'||OLD.id); INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='m:'||NEW.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='m:'||NEW.id); INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='t:'||OLD.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='t:'||OLD.id); INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='t:'||NEW.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='t:'||NEW.id); INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='c:'||OLD.conversation_id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='c:'||OLD.conversation_id); INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='c:'||NEW.conversation_id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='c:'||NEW.conversation_id); END;
